INSERT INTO summaries (entry_id,body,source_url,quality,retrieved_at) VALUES ('hanuman','印度史诗《罗摩衍那》中的神猴形象。其与孙悟空之间的影响关系存在长期讨论，P1 仅将其作为待核验候选来源。','https://en.wikipedia.org/wiki/Hanuman','curated','2026-10-10T00:00:00.000Z'),('monkey-pilgrim','早期取经故事中的猴行者形象，是《西游记》孙悟空形成过程中的重要前身之一。','https://en.wikipedia.org/wiki/Journey_to_the_West','curated','2026-10-10T00:00:00.000Z'),('wuzhiqi','中国水怪传说中的猿猴形象。其与孙悟空的关系尚有争议，在图谱中以推测关联表示。','https://en.wikipedia.org/wiki/Wuzhiqi','curated','2026-10-10T00:00:00.000Z'),('sun-wukong','《西游记》的核心角色。P1 以这一文学版本作为 Trace 中心，观察早期候选来源和现代改编如何汇聚与分叉。','https://en.wikipedia.org/wiki/Monkey_King','curated','2026-10-10T00:00:00.000Z'),('dragon-ball','鸟山明《龙珠》的主角，以《西游记》孙悟空为明确灵感来源，形成全球流行文化中的新分支。','https://en.wikipedia.org/wiki/Goku','curated','2026-10-10T00:00:00.000Z'),('saiyuki','峰仓和也作品《最游记》中的孙悟空版本，是《西游记》角色在日本现代漫画中的再创作。','https://en.wikipedia.org/wiki/Saiyuki_(manga)','curated','2026-10-10T00:00:00.000Z'),('a-chinese-odyssey','《大话西游》通过至尊宝 / 孙悟空重新讲述经典角色，在华语流行文化中形成广泛影响。','https://en.wikipedia.org/wiki/A_Chinese_Odyssey','curated','2026-10-10T00:00:00.000Z'),('black-myth','以《西游记》为背景的动作角色扮演游戏，是孙悟空母题在当代游戏媒介中的重要传播节点。','https://en.wikipedia.org/wiki/Black_Myth:_Wukong','curated','2026-10-10T00:00:00.000Z'),('ramayana','古印度史诗，为哈奴曼形象的重要文本来源。','https://en.wikipedia.org/wiki/Ramayana','curated','2026-10-10T00:00:00.000Z'),('zaju','在长篇小说之前，西游题材已经通过戏曲等形式持续发展。','https://en.wikipedia.org/wiki/Journey_to_the_West','curated','2026-10-10T00:00:00.000Z'),('tv-journey','央视电视剧《西游记》塑造了华语观众熟悉的孙悟空荧幕形象。','https://en.wikipedia.org/wiki/Journey_to_the_West_(1986_TV_series)','curated','2026-10-10T00:00:00.000Z'),('enma','《最游记》的续作分支，用于呈现现代改编继续演化的上下文。','https://en.wikipedia.org/wiki/Saiyuki_(manga)','curated','2026-10-10T00:00:00.000Z') ON CONFLICT(entry_id, source_url, body) DO UPDATE SET retrieved_at = excluded.retrieved_at;
